mapper.select:
SELECT NVL(SUM(score), 0)
FROM song_score_tbl
WHERE user_id = #{userId}
  AND song_id = #{songId}
  AND score IN (300, -300)

SELECT COUNT(*)
FROM song_score_tbl
WHERE user_id = #{userId}
  AND song_id = #{songId}
  AND score = 300

mapper.delete:
DELETE FROM song_score_tbl
WHERE score_id = (
    SELECT MIN(score_id)
    FROM song_score_tbl
    WHERE user_id = #{userId}
      AND song_id = #{songId}
      AND score = 300
)

